function render(t){update(t);backdrop(t);ground();siteDetails();buildings();rig();hole();if(state.started&&state.depth>0&&state.depth<6371000&&state.depth%1500<500){ctx.save();ctx.globalAlpha=.14;ctx.fillStyle='#ffbb69';ctx.fillRect(0,0,W,H);ctx.restore()}requestAnimationFrame(render)}requestAnimationFrame(render);
const target=6371;let fuelSeconds=0,paidAt=0,nearby='',panelOpen=false,keys={},lastUpdate=performance.now();
const places={rig:{x:0,z:8,name:'Drill Platform'},lab:{x:7,z:3,name:'Science Lab'},shop:{x:-7,z:3,name:'Oil Supply Shack'}};
function distance(place){return Math.hypot(state.x-place.x,state.z-place.z)}
function nearestPlace(){let best='',d=Infinity;for(const [id,p] of Object.entries(places)){const n=distance(p);if(n<d){best=id;d=n}}return d<3.6?best:''}
function showToast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function updateHud(){ $('#cash').textContent='$'+Math.floor(state.cash).toLocaleString();$('#oil').textContent=state.oil;$('#power').textContent=state.drilling?Math.ceil(fuelSeconds/12*100)+'%':(fuelSeconds>0?Math.ceil(fuelSeconds/12*100)+'%':'OFF');$('#depth').textContent=Math.floor(state.depth).toLocaleString();$('#depthBar').style.width=Math.min(100,state.depth/target*100)+'%';$('#depthHint').textContent=state.depth>=target?'THE CORE IS WITHIN REACH':`Core distance: ${Math.max(0,target-state.depth).toLocaleString()} km`;const zone=nearestPlace();nearby=zone||'';const tags={rig:['DRILL SITE','The Borehead','Steel, stone, and a long way down.'],lab:['FIELD STATION','Science Lab','The next breakthrough starts here.'],shop:['SUPPLY DEPOT','Oil Supply Shack','Fuel for the journey below.']};const info=tags[zone]||['EARTH · SURFACE','The Last Light','A drill site at the edge of everything.'];$('#zoneTag').textContent=info[0];$('#zoneName').textContent=info[1];$('#zoneSub').textContent=info[2];const prompt=$('#interaction');if(zone&&!panelOpen){prompt.style.opacity=1;prompt.querySelector('span').textContent=zone==='rig'?'Rig controls · refuel / drill':zone==='lab'?'Enter Science Lab':'Browse the oil shop'}else prompt.style.opacity=0;const mine=$('#mineBtn');mine.textContent=state.drilling?'■  STOP DRILLING':(zone==='rig'&&fuelSeconds===0&&state.oil>0?'▣  LOAD OIL & DRILL':'⛏  START DRILLING');mine.disabled=zone!=='rig'&&!state.drilling;mine.classList.toggle('secondary',zone!=='rig'&&!state.drilling)}
function update(t){const dt=Math.min(.06,(t-lastUpdate)/1000||0);lastUpdate=t;if(state.started&&!panelOpen){let f=0,s=0;if(keys.KeyW||keys.ArrowUp)f++;if(keys.KeyS||keys.ArrowDown)f--;if(keys.KeyA||keys.ArrowLeft)s--;if(keys.KeyD||keys.ArrowRight)s++;const mag=Math.hypot(f,s)||1;const speed=5.1*dt;state.x+=(Math.sin(state.yaw)*f+Math.cos(state.yaw)*s)*speed/mag;state.z+=(Math.cos(state.yaw)*f-Math.sin(state.yaw)*s)*speed/mag;state.x=clamp(state.x,-18,18);state.z=clamp(state.z,-12,24);state.walk+=Math.abs(f)+Math.abs(s);state.shake=(Math.abs(f)+Math.abs(s))?Math.sin(state.walk*2)*.7:0;if(state.drilling){if(fuelSeconds>0){fuelSeconds-=dt;const rate=145*(1+state.upgrade*.35);state.depth=Math.min(target,state.depth+rate*dt);const milestone=Math.floor(state.depth/500);if(milestone>paidAt){paidAt=milestone;const reward=45+state.upgrade*10;state.cash+=reward;showToast(`Core samples secured · +$${reward}`)}if(state.depth>=target){state.depth=target;state.drilling=false;state.core=true;showCore()}}else if(state.oil>0){state.oil--;fuelSeconds=12;showToast('Fresh canister loaded automatically.')}else{state.drilling=false;showToast('Rig is out of oil. Visit the supply shack.')}}}updateHud()}
function openPanel(place){if(!place)return;panelOpen=true;$('#panelback').classList.add('show');const title=$('#panelTitle'),desc=$('#panelDesc'),eyebrow=$('#panelEyebrow'),cards=$('#cards'),note=$('#panelNote');cards.innerHTML='';if(place==='shop'){eyebrow.textContent='SUPPLY DEPOT · EARTH';title.textContent='Oil Supply Shack';desc.textContent='Keep the borehead turning. Every canister buys 12 seconds of drilling.';cards.innerHTML=`<article class="card"><div class="icon">▰</div><div class="cardtext"><strong>Industrial oil canister</strong><p>One sealed canister · 12 seconds at the rig</p></div><div><div class="price">$55</div><button class="action small" data-buy="1">BUY ONE</button></div></article><article class="card"><div class="icon">▰▰</div><div class="cardtext"><strong>Expedition crate</strong><p>Three canisters · best value for a deep run</p></div><div><div class="price">$145</div><button class="action small" data-buy="3">BUY 3</button></div></article>`;note.textContent='Fuel is carried with you. At the rig, press E to load a canister; any remaining canisters are loaded automatically as you drill.'}else if(place==='lab'){eyebrow.textContent='FIELD STATION · RESEARCH';title.textContent='Science Lab';desc.textContent='Turn every sample into a smarter, faster expedition.';const next=state.upgrade+1;cards.innerHTML=state.upgrade<2?`<article class="card"><div class="icon">⚙</div><div class="cardtext"><strong>Thermal drill head · Mk ${next}</strong><p>${state.upgrade?'Deep-core ceramic teeth.':'Hardened tungsten teeth.'} Increases drilling speed by 35%.</p></div><div><div class="price">$${state.upgrade?260:180}</div><button class="action small" data-upgrade>INSTALL</button></div></article>`:`<article class="card"><div class="icon">✓</div><div class="cardtext"><strong>Drill head · Mk II</strong><p>Maximum field-grade bore speed installed.</p></div><div class="price">COMPLETE</div></article>`;cards.innerHTML+=`<article class="card"><div class="icon">⌁</div><div class="cardtext"><strong>Core sample analysis</strong><p>Depth milestones pay out automatically. Current rig speed: ${Math.round(145*(1+state.upgrade*.35))} km/s.</p></div><div class="price">LIVE DATA</div></article>`;note.textContent='Research upgrades are permanent. Mine samples to earn credits, then bring them back here.'}else{eyebrow.textContent='BOREHEAD · FIELD CONTROLS';title.textContent=state.core?'Earth’s Core': 'Mining Rig';desc.textContent=state.core?'You made it all the way down. The impossible is now a place.':'The top of the rig is the only place to load oil and begin the descent.';cards.innerHTML=state.core?`<article class="card"><div class="icon">✦</div><div class="cardtext"><strong>Expedition complete</strong><p>You drilled ${target.toLocaleString()} km through the Earth and reached the core.</p></div><div class="price">LEGEND</div></article>`:`<article class="card"><div class="icon">${fuelSeconds>0?'◉':'▰'}</div><div class="cardtext"><strong>${fuelSeconds>0?'Oil line primed':'Oil at the top of the rig'}</strong><p>${fuelSeconds>0?`Rig powered · ${Math.ceil(fuelSeconds)} seconds remain.`:state.oil?`${state.oil} canister${state.oil===1?'':'s'} in your pack.`:'No fuel on the rig. Buy canisters at the supply shack.'}</p></div><div><div class="price">${fuelSeconds>0?'READY':state.oil+' IN PACK'}</div><button class="action small" data-refuel ${!state.oil||fuelSeconds>0?'disabled':''}>LOAD OIL</button></div></article><article class="card"><div class="icon">⛏</div><div class="cardtext"><strong>${Math.floor(state.depth).toLocaleString()} km drilled</strong><p>Drill rate: ${Math.round(145*(1+state.upgrade*.35))} km/s · Each canister runs for 12 seconds.</p></div><button class="action small" data-drill ${fuelSeconds<=0&&!state.oil?'disabled':''}>${state.drilling?'STOP':'DRILL'}</button></article>`;note.textContent='Depth samples are automatically exchanged for credits every 500 km. You can walk away while the rig keeps working.'}cards.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buyOil(+b.dataset.buy));const up=cards.querySelector('[data-upgrade]');if(up)up.onclick=buyUpgrade;const ref=cards.querySelector('[data-refuel]');if(ref)ref.onclick=loadOil;const drill=cards.querySelector('[data-drill]');if(drill)drill.onclick=toggleDrill;updateHud()}

