function toggleDrill(){if(state.core){showCore();return}if(!state.drilling){if(fuelSeconds<=0){if(state.oil<=0){showToast('No oil in your pack. Visit the supply shack.');return}state.oil--;fuelSeconds=12;showToast('Oil canister loaded at the top of the rig.')}state.drilling=true;showToast('Borehead engaged. Keep an eye on your fuel.')}else{state.drilling=false;showToast('Drill paused. Your depth is saved.')}closePanel();updateHud()}
